import {$,$$,esc,showToast} from "./dom.js";
import {appState,events,products,placeholders,fixedEnvelopeFields,supportedLanguages} from "./state.js";
import {openLanguageDrawer} from "./language-editor.js";
import {renderAnnotations} from "./annotations.js";

const steps=[[1,"基础信息与消息","内容、占位符、跳转、多语言"],[2,"触发与接收者","四类触发、固定信封、目标用户"],[3,"投递与生命周期","优先级、频控、结束与校验"]];
const activeProduct=()=>products.find(p=>p.id===appState.selectedProductId)||products[0];
const activeEvent=()=>events.find(e=>e.id===appState.rule.eventId)||events.find(e=>e.productId===appState.selectedProductId&&e.status==="已发布");
const selectedMessage=()=>appState.message.values["en-US"]||(appState.message.values["en-US"]={title:"",body:""});
const supportedLocales=()=>appState.selectedLocales.length;
const linkValid=value=>/^cozy:\/\/[A-Za-z0-9._~!$&'()*+,;=:@%/?#{}-]{1,480}$/.test(value)&&!/[\s<>"']/.test(value);
const unsupportedTokens=()=>[...new Set(`${selectedMessage().title} ${selectedMessage().body}`.match(/\$\{[^}]+\}/g)||[])].filter(token=>!placeholders.some(p=>p.token===token));
const invalidTokens=()=>placeholders.filter(p=>p.supported.includes(appState.rule.triggerType)===false&&(`${selectedMessage().title} ${selectedMessage().body}`).includes(p.token)).map(p=>p.token);

function drawerShell(){const p=activeProduct();return `<div class="drawer-host is-open" id="ruleDrawer"><div class="drawer-mask" data-close-drawer></div><aside class="drawer" role="dialog" aria-modal="true" aria-label="${appState.editingRule?"编辑":"新建"}推送规则"><header class="drawer-header"><div class="drawer-title"><h2>${appState.editingRule?"编辑":"新建"}推送规则</h2><p>${esc(p.name)} · ${esc(appState.rule.name||"未命名规则")}</p></div><button class="icon-btn" data-close-drawer>×</button></header><div class="drawer-body"><nav class="step-nav" data-anchor="step-nav">${steps.map(([id,title,sub])=>`<button class="step-item ${appState.ruleStep===id?"active":""}" data-step="${id}"><span class="step-index">${id}</span><span class="step-copy"><strong>${title}</strong><small>${sub}</small></span></button>`).join("")}</nav><section class="drawer-content" id="ruleStepContent">${renderStep()}</section></div>${footer()}</aside></div>`}
function footer(){return `<footer class="drawer-footer" data-anchor="drawer-footer"><span class="save-hint">自动保存上次编辑：刚刚 · 产品 ${esc(activeProduct().name)}</span><div class="footer-actions"><button class="el-btn" data-draft>保存草稿</button><button class="el-btn" data-prev ${appState.ruleStep===1?"disabled":""}>上一步</button>${appState.ruleStep<3?'<button class="el-btn el-btn--primary" data-next>下一步</button>':'<button class="el-btn el-btn--primary" data-enable>保存并启用</button>'}</div></footer>`}

function placeholderPanel(target){return `<div class="placeholder-panel" data-anchor="placeholder-panel">${placeholders.map(p=>{const ok=p.supported.includes(appState.rule.triggerType);return `<button type="button" class="placeholder ${ok?"":"is-disabled"}" data-placeholder="${esc(p.token)}" data-target="${target}" ${ok?"":"disabled"} title="${ok?`插入 ${p.label}`:`当前 ${appState.rule.triggerType} 触发无法提供此变量`}">${esc(p.token)}</button>`}).join("")}</div><p class="form-help">点击变量插入当前光标位置；灰色变量由当前触发载荷无法解析。</p>`}
function basicStep(){const msg=selectedMessage();const p=activeProduct();const selectedNames=appState.selectedLocales.map(code=>supportedLanguages.find(x=>x[0]===code)?.[1]||code).join("、");return `<div class="form-section"><div class="section-title"><h3>基础信息</h3><p>产品上下文已锁定</p></div><div class="form-grid"><label class="form-row full"><span class="form-label"><i class="required">*</i>规则名称</span><input class="el-input" data-field="name" value="${esc(appState.rule.name)}" maxlength="50"><p class="form-help">2-50 字，仅后台可见。</p></label><label class="form-row"><span class="form-label">当前产品</span><div class="readonly-field">${esc(p.name)} · ${esc(p.id)}</div></label><label class="form-row"><span class="form-label"><i class="required">*</i>消息分类</span><select class="el-select" data-field="category">${["安全","维护","耗材","通知","系统","固件","安防"].map(v=>`<option ${v===appState.rule.category?"selected":""}>${v}</option>`).join("")}</select></label></div></div><div class="form-section" data-anchor="message-editor"><div class="section-title"><h3>推送消息</h3><p>规则内编辑，默认语言：English</p></div><div class="help-alert">英语始终作为 fallback 且不可取消；发布只校验已勾选语言。当前已选 ${supportedLocales()} / 18：${esc(selectedNames)}。</div><div class="form-grid"><label class="form-row full"><span class="form-label"><i class="required">*</i>Title · English</span><input id="messageTitle" class="el-input" data-message-key="title" value="${esc(msg.title)}" maxlength="100"><div class="form-help">支持占位符，长度不超过 100。</div>${placeholderPanel("title")}</label><label class="form-row full"><span class="form-label"><i class="required">*</i>Body · English</span><textarea id="messageBody" class="el-textarea" data-message-key="body" maxlength="200">${esc(msg.body)}</textarea><div class="form-help">支持占位符，长度不超过 200。</div>${placeholderPanel("body")}</label><div class="form-row full" data-anchor="jump-mode"><span class="form-label">跳转页面</span><div class="radio-row">${[["none","不跳转"],["preset","产品预设页面"],["custom","自定义 cozy:// 深链"]].map(([v,t])=>`<label class="choice-card ${appState.message.cozyLinkMode===v?"selected":""}"><input type="radio" name="linkMode" value="${v}" ${appState.message.cozyLinkMode===v?"checked":""}> <span class="choice-copy"><strong>${t}</strong><small>${v==="custom"?"仅接受 cozy://，禁止 HTTPS":"当前产品可用"}</small></span></label>`).join("")}</div>${appState.message.cozyLinkMode==="preset"?`<select class="el-select" data-preset-link style="margin-top:10px">${p.presetLinks.map(x=>`<option value="${esc(x.id)}" ${x.id===appState.message.presetLinkId?"selected":""}>${esc(x.label)} · ${esc(x.uri)}</option>`).join("")}</select>`:""}${appState.message.cozyLinkMode==="custom"?`<input class="el-input" data-custom-link value="${esc(appState.message.cozyLink)}" placeholder="cozy://device/{deviceId}/safety" style="margin-top:10px"><p class="form-help">协议、格式、长度和非法空格将在发布时校验；旧链接仅在编辑/发布时校验，不批量停用线上规则。</p>`:""}</div><div class="form-row full" data-anchor="language-entry"><div class="help-alert success">语言选择：${esc(selectedNames||"English")}。取消语言会保留草稿，但不参与发布校验。</div><button class="el-btn" data-open-language>编辑 18 语言 KV 矩阵</button></div></div></div>`}

function recipientCopy(){const t=appState.rule.triggerType;if(t==="event")return "自定义事件：userIds 有值取其集合；为空时取当前产品全部绑定用户。";return `${t==="device"?"设备":t==="cloud"?"云端":"耗材"}触发：userIds 有值取其集合；为空时以 deviceId 查询绑定用户。`}
function eventOptions(){return events.filter(e=>e.productId===appState.selectedProductId&&e.status==="已发布")}
function triggerDetail(){const r=appState.rule;if(r.triggerType==="device")return `<label class="form-row full"><span class="form-label"><i class="required">*</i>设备触发条件</span><select class="el-select" data-field="deviceCondition"><option ${r.deviceCondition.includes("溢奶")?"selected":""}>溢奶事件 · level ≥ 2</option><option ${r.deviceCondition.includes("时长")?"selected":""}>吸乳时长 · ≥ 30 分钟</option><option ${r.deviceCondition.includes("结束")?"selected":""}>吸乳结束事件</option></select><p class="form-help">来源：当前产品物模型属性或事件；恢复条件在步骤 3 自动按同源目录筛选。</p></label>`;if(r.triggerType==="cloud")return `<label class="form-row full"><span class="form-label"><i class="required">*</i>云端触发条件</span><select class="el-select" data-field="cloudCondition"><option ${r.cloudCondition.includes("倒计时")?"selected":""}>喂养提醒倒计时 ≤ 30 分钟</option><option>服务订阅即将到期</option><option>云端任务异常</option></select><p class="form-help">来源：当前产品云端事件；userIds 可由事件载荷携带。</p></label>`;if(r.triggerType==="consumable")return `<label class="form-row full"><span class="form-label"><i class="required">*</i>耗材触发条件</span><select class="el-select" data-field="consumableCondition"><option ${r.consumableCondition.includes("不足")?"selected":""}>滤芯余量不足</option><option>耗材已耗尽</option><option>耗材寿命即将结束</option></select><p class="form-help">来源：当前产品耗材事件；恢复/重置/更换事件在步骤 3 选择。</p></label>`;const event=activeEvent()||eventOptions()[0];if(!event)return `<div class="help-alert warning">当前产品暂无已发布事件。请先在事件管理发布事件，规则才能选择事件触发。</div>`;return `<div class="form-row full" data-anchor="event-field"><span class="form-label"><i class="required">*</i>当前产品事件</span><select class="el-select" data-field="eventId">${eventOptions().map(e=>`<option value="${esc(e.id)}" ${e.id===event.id?"selected":""}>${esc(e.name)} · ${esc(e.eventType)}</option>`).join("")}</select><div class="schema-box" data-anchor="fixed-envelope"><div class="schema-head"><span>固定信封（只读）</span><span>${esc(event.schemaVersion)} · ${esc(event.callerId)}</span></div><div class="event-schema-grid">${fixedEnvelopeFields.map(f=>`<div><code>${esc(f.key)}</code><small>${esc(f.type)}${f.required?" · required":" · optional"}</small></div>`).join("")}</div><pre>${esc(event.payloadSchema)}</pre></div><p class="form-help">caller_id 从鉴权凭证解析；调用请求不可填写。自定义 Payload 仅允许深度、大小、类型和 $ref 受限的 JSON Schema。</p><button class="op-link" data-open-events>打开事件管理</button></div>`}
function triggerStep(){const types=[["device","设备触发","物模型属性 / 事件"],["cloud","云端触发","产品云端事件"],["consumable","耗材触发","恢复、重置、更换"],["event","自定义事件","当前产品已发布事件"]];return `<div class="form-section"><div class="section-title"><h3>触发源</h3><p>事件触发属于需求范围，且按产品隔离</p></div><div class="form-row full" data-anchor="trigger-type"><span class="form-label"><i class="required">*</i>触发类型</span><div class="radio-row">${types.map(([v,t,s])=>`<label class="choice-card ${appState.rule.triggerType===v?"selected":""}"><input type="radio" name="triggerType" value="${v}" ${appState.rule.triggerType===v?"checked":""}><span class="choice-copy"><strong>${t}</strong><small>${s}</small></span></label>`).join("")}</div></div><div class="form-grid">${triggerDetail()}</div></div><div class="form-section"><div class="section-title"><h3>目标用户解析</h3><p>不再提供独立用户属性筛选</p></div><div class="form-grid"><div class="form-row full" data-anchor="candidate-users"><span class="form-label">固定解析规则</span><div class="readonly-field">${esc(recipientCopy())}</div><p class="form-help">单点 User 通过长度为 1 的 userIds 传入；批量 User 通过数组传入。规则不维护 B 端升级接收人。</p></div><div class="form-row full" data-anchor="audience-intersection"><div class="summary-card"><h4>目标用户</h4><p>最终目标用户 = 触发载荷解析集合。若 payload 带 userIds，使用该集合；为空时按触发源获取设备绑定用户或当前产品全部绑定用户。条件筛选与 userId 已移除。</p></div></div></div></div>`}

function compatibleEndEvents(){const r=appState.rule;const kind=r.triggerType;return events.filter(e=>e.productId===appState.selectedProductId&&e.status==="已发布"&&(kind==="event"?e.id!==r.eventId:e.triggerKind===kind)&&e.correlationKey===r.correlationKey&&(kind==="device"?e.id.includes("recovered"):kind==="consumable"?e.id.includes("replaced")||e.id.includes("reset"):true))}
function frequencyTimeline(){const r=appState.rule;if(r.lifecycle==="continuous")return `<div class="timeline"><div class="timeline-title">连续实例状态</div><div class="timeline-row"><span class="timeline-dot active"></span><span>开始信号</span><b>立即发送</b><small>实例 ${esc(r.correlationKey)}#a81f · active</small></div><div class="timeline-row"><span class="timeline-dot"></span><span>重复开始信号</span><b>刷新实例</b><small>更新最新 Payload，不创建并行提醒</small></div><div class="timeline-row"><span class="timeline-dot"></span><span>结束信号</span><b>结束并关闭</b><small>${r.endEventId?esc(r.endEventId):"未配置，按受限模式停止"}</small></div></div>`;if(r.priority==="P0")return `<div class="timeline p0"><div class="timeline-title">P0 全量直发时间线</div><div class="timeline-row"><span class="timeline-dot active"></span><span>每个唯一 idempotencyKey</span><b>立即发送</b><small>只做 replay 幂等去重，不丢弃、不合并</small></div></div>`;return `<div class="timeline"><div class="timeline-title">频控时间线 · ${r.strategy==="mergeLast"?"合并发送（取最后一次）":"后续丢弃"}</div><div class="timeline-row"><span class="timeline-dot active"></span><span>t0 首条事件</span><b>立即发送</b><small>窗口开始，最小间隔 ${r.minIntervalMinutes} 分钟</small></div><div class="timeline-row"><span class="timeline-dot"></span><span>t+2 分钟</span><b>${r.strategy==="mergeLast"?"保留最后一次":"suppressed"}</b><small>${r.strategy==="mergeLast"?"窗口内不生成摘要文案":"窗口内事件只记录 suppressed"}</small></div><div class="timeline-row"><span class="timeline-dot"></span><span>窗口结束</span><b>${r.strategy==="mergeLast"?"发送最后一次内容":"无额外发送"}</b><small>按规则级独立策略执行</small></div></div>`}
function deliveryStep(){
  const r=appState.rule; const endOptions=compatibleEndEvents(); const p0=r.priority==="P0"; const isContinuous=r.lifecycle==="continuous";
  const priorityCards=[["P0","紧急","安全风险，必须即时感知"],["P1","重要","需要用户关注或处理的异常"],["P2","普通","耗材、维护、状态类通知"]].map(([v,t,d])=>`<label class="choice-card ${r.priority===v?"selected":""}"><input type="radio" name="priority" value="${v}" ${r.priority===v?"checked":""}><span class="choice-copy"><strong>${v} · ${t}</strong><small>${d}</small></span></label>`).join("");
  let frequencyMarkup="";
  if(isContinuous){
    frequencyMarkup=`<div class="form-row full" data-anchor="reminder-interval"><label class="form-label"><i class="required">*</i>提醒间隔（分钟）</label><input class="el-input" type="number" data-field="reminderIntervalMinutes" min="5" max="10080" value="${r.reminderIntervalMinutes}"><p class="form-help">连续模式隐藏丢弃/合并；重复开始信号只刷新同一 ${esc(r.correlationKey)} 关联实例。</p></div>`;
  }else if(p0){
    frequencyMarkup=`<div class="help-alert danger"><strong>P0 约束：</strong>全量直发；不丢弃、不合并，仅幂等 replay 去重。</div>`;
  }else{
    const strategyCards=[["discard","后续丢弃","窗口首条立即发送，后续记录 suppressed"],["mergeLast","合并发送（取最后一次）","窗口结束发送最后一次事件内容，不生成摘要文案"]].map(([v,t,d])=>`<label class="choice-card ${r.strategy===v?"selected":""}"><input type="radio" name="frequency" value="${v}" ${r.strategy===v?"checked":""}><span class="choice-copy"><strong>${t}</strong><small>${d}</small></span></label>`).join("");
    frequencyMarkup=`<div class="form-row full" data-anchor="frequency-strategy"><span class="form-label"><i class="required">*</i>后续事件策略</span><div class="radio-row">${strategyCards}</div><label class="form-row" style="margin-top:12px"><span class="form-label">最小发送间隔（分钟）</span><input class="el-input" type="number" data-field="minIntervalMinutes" min="5" max="10080" value="${r.minIntervalMinutes}"><p class="form-help">5 分钟至 7 天；规则级独立设置。</p></label></div>`;
  }
  const endMarkup=isContinuous?`<div class="form-section" data-anchor="lifecycle-field"><div class="section-title"><h3>结束条件</h3><p>跟随开始触发源并共享关联键</p></div><label class="form-row full"><span class="form-label">关联键</span><select class="el-select" data-field="correlationKey">${["deviceId","userId","productId"].map(v=>`<option ${r.correlationKey===v?"selected":""}>${v}</option>`).join("")}</select><p class="form-help">开始与结束必须使用相同关联键；选择器只展示兼容项。</p></label><label class="form-row full"><span class="form-label">结束事件</span><select class="el-select" data-field="endEventId"><option value="">不配置 — 受限模式</option>${endOptions.map(e=>`<option value="${esc(e.id)}" ${r.endEventId===e.id?"selected":""}>${esc(e.name)} · ${esc(e.eventType)}</option>`).join("")}</select><p class="form-help">${endOptions.length?"来源：当前产品同触发源的恢复、重置、更换或已发布事件。":"当前关联键没有兼容结束事件，只能采用受限模式。"}</p></label><label class="choice-card ${r.limited?"selected":""}" style="margin-top:10px"><input type="checkbox" data-field="limited" ${r.limited?"checked":""}><span class="choice-copy"><strong>采用受限模式</strong><small>无结束条件时按 72 小时 / 100 次运行，系统硬顶 168 小时 / 500 次</small></span></label></div>`:"";
  return `<div class="form-section" data-anchor="priority-field"><div class="section-title"><h3>优先级</h3><p>P0/P1/P2 约束独立呈现</p></div><div class="radio-row">${priorityCards}</div></div><div class="form-section" data-anchor="delivery-mode"><div class="section-title"><h3>提醒模式与频控</h3><p>${isContinuous?"连续模式与丢弃/合并互斥":"事件触发后执行一次"}</p></div><div class="radio-row"><label class="choice-card ${!isContinuous?"selected":""}"><input type="radio" name="lifecycle" value="single" ${!isContinuous?"checked":""}><span class="choice-copy"><strong>单次提醒</strong><small>首条事件触发一次</small></span></label><label class="choice-card ${isContinuous?"selected":""}"><input type="radio" name="lifecycle" value="continuous" ${isContinuous?"checked":""}><span class="choice-copy"><strong>连续提醒</strong><small>按提醒间隔直至结束或硬上限</small></span></label></div>${frequencyMarkup}</div>${endMarkup}<div class="form-section" data-anchor="hard-cap"><div class="section-title"><h3>受限模式硬上限</h3><p>连续模式必有结束条件或受限模式</p></div><div class="form-grid"><label class="form-row"><span class="form-label">最大持续时间（小时）</span><input class="el-input" type="number" data-field="maxHours" min="1" max="168" value="${r.maxHours}"><p class="form-help">默认 72h，系统硬顶 168h。</p></label><label class="form-row"><span class="form-label">最大提醒次数</span><input class="el-input" type="number" data-field="maxCount" min="1" max="500" value="${r.maxCount}"><p class="form-help">默认 100 次，系统硬顶 500 次。</p></label></div></div><div class="form-section" data-anchor="fuse-state"><div class="section-title"><h3>P0 异常风暴保护</h3><p>平台运维告警，不新增 B 端接收人</p></div><div class="fuse-card ${appState.fuseState.status}"><div><strong>${appState.fuseState.status==="open"?"熔断中":appState.fuseState.status==="half-open"?"半开探测":"正常"}</strong><span> ${appState.fuseState.uniquePerMinute} unique triggers/min/rule · 静默 ${appState.fuseState.quietMinutes} min</span></div><p>${appState.fuseState.status==="open"?"超过 100 个唯一触发/分钟，停止发送并写审计；静默 5 分钟后半开。":"超过 100 个唯一触发/分钟自动熔断，首个正常触发通过后恢复。"}</p><div class="fuse-actions"><button class="el-btn" data-fuse="open">模拟 >100/min</button><button class="el-btn" data-fuse="half-open">静默 5 分钟</button><button class="el-btn" data-fuse="closed">恢复</button></div></div></div><div class="form-section" data-anchor="frequency-timeline"><div class="section-title"><h3>投递时间线</h3><p>用于校验状态变化</p></div>${frequencyTimeline()}</div><div class="form-section" data-anchor="validation"><div class="section-title"><h3>发布校验</h3><p>只校验当前选中语言</p></div>${validationList()}</div>`;
}
function selectedLanguageErrors(){const missing=[];const unknown=[];const unsupported=[];appState.selectedLocales.forEach(code=>{const v=appState.message.values[code]||{};if(!v.title?.trim()||!v.body?.trim())missing.push(code);[...new Set(`${v.title||""} ${v.body||""}`.match(/\$\{[^}]+\}/g)||[])].forEach(token=>{const p=placeholders.find(x=>x.token===token);if(!p)unknown.push(`${code}: ${token}`);else if(!p.supported.includes(appState.rule.triggerType))unsupported.push(`${code}: ${token}`)})});return {missing,unknown,unsupported}}function validationList(){const msg=selectedMessage();const localeErrors=selectedLanguageErrors();const strategyValid=appState.rule.lifecycle==="continuous"||appState.rule.priority==="P0"||["discard","mergeLast"].includes(appState.rule.strategy);const items=[[!!appState.rule.name,"规则名称与当前产品上下文"],[!!msg.title.trim()&&!!msg.body.trim(),"English title / body"],[localeErrors.missing.length===0,"已选语言 title / body"],[unsupportedTokens().length===0&&localeErrors.unknown.length===0,"占位符均在预设列表"],[invalidTokens().length===0&&localeErrors.unsupported.length===0,"当前触发类型可解析占位符"],[appState.message.cozyLinkMode!=="custom"||linkValid(appState.message.cozyLink),"cozy:// 跳转格式"],[strategyValid,"单次 P1/P2 已选择后续策略"],[appState.rule.lifecycle!=="continuous"||!!appState.rule.endEventId||!!appState.rule.limited,"结束条件或受限模式硬顶"],[appState.rule.maxHours<=168&&appState.rule.maxCount<=500,"受限模式系统硬顶"]];return `<div class="validation-list">${items.map(([ok,label])=>`<div class="validation-item"><span>${ok?"✓":"!"} ${label}</span><span class="el-tag el-tag--${ok?"success":"danger"} is-plain">${ok?"通过":"阻断"}</span></div>`).join("")}</div>${localeErrors.missing.length?`<div class="help-alert danger">已选语言缺少内容：${esc(localeErrors.missing.join("、"))}</div>`:""}${unsupportedTokens().length||localeErrors.unknown.length?`<div class="help-alert danger">未知变量：${esc([...unsupportedTokens(),...localeErrors.unknown].join("、"))}</div>`:""}${invalidTokens().length||localeErrors.unsupported.length?`<div class="help-alert danger">当前触发无法提供：${esc([...invalidTokens(),...localeErrors.unsupported].join("、"))}</div>`:""}`}

function renderStep(){return appState.ruleStep===1?basicStep():appState.ruleStep===2?triggerStep():deliveryStep()}
function triggerLabel(){const r=appState.rule;if(r.triggerType==="device")return r.deviceCondition;if(r.triggerType==="cloud")return r.cloudCondition;if(r.triggerType==="consumable")return r.consumableCondition;return activeEvent()?.name||r.eventId}
function ruleSummary(){const r=appState.rule;const mode=r.lifecycle==="continuous"?`连续提醒，每 ${r.reminderIntervalMinutes} 分钟，直到 ${r.endEventId||"受限模式硬上限"}`:r.priority==="P0"?"P0 全量直发，仅幂等 replay 去重":`${r.strategy==="mergeLast"?"合并发送（取最后一次）":"后续丢弃"}，最小间隔 ${r.minIntervalMinutes} 分钟`;return `当【${triggerLabel()}】发生时，按【${recipientCopy()}】解析目标用户；以【${mode}】发送 English fallback 与已选语言消息。`}

export function openRuleDrawer({edit=false,onOpenEvents}={}){appState.editingRule=edit;appState.ruleStep=1;$("#overlayRoot").innerHTML=drawerShell();wire(onOpenEvents);renderAnnotations("rule1","规则配置 · 步骤 1/3")}
function rerender(onOpenEvents){const c=$("#ruleStepContent");if(!c)return;c.innerHTML=renderStep();$$(".step-item").forEach(el=>el.classList.toggle("active",Number(el.dataset.step)===appState.ruleStep));$(".drawer-footer").outerHTML=footer();wireStep(onOpenEvents);renderAnnotations(`rule${appState.ruleStep}`,`规则配置 · 步骤 ${appState.ruleStep}/3`)}
function wire(onOpenEvents){const host=$("#ruleDrawer");host.querySelectorAll("[data-close-drawer]").forEach(el=>el.addEventListener("click",closeRuleDrawer));host.querySelectorAll("[data-step]").forEach(el=>el.addEventListener("click",()=>{appState.ruleStep=Number(el.dataset.step);rerender(onOpenEvents)}));wireStep(onOpenEvents)}
function wireStep(onOpenEvents){const host=$("#ruleDrawer");if(!host)return;
  host.querySelectorAll("[data-field]").forEach(el=>{const eventName=(el.tagName==="INPUT"&&el.type!=="number")||el.tagName==="TEXTAREA"?"input":"change";el.addEventListener(eventName,()=>{appState.rule[el.dataset.field]=el.type==="checkbox"?el.checked:el.value;if(el.dataset.field==="correlationKey"&&!compatibleEndEvents().some(e=>e.id===appState.rule.endEventId))appState.rule.endEventId="";if(el.dataset.field==="endEventId"&&el.value)appState.rule.limited=false;if(["triggerType","eventId","correlationKey","lifecycle","endEventId","limited"].includes(el.dataset.field))rerender(onOpenEvents)})});
  host.querySelectorAll('input[name="priority"]').forEach(el=>el.addEventListener("change",()=>{appState.rule.priority=el.value;rerender(onOpenEvents)}));
  host.querySelectorAll('input[name="triggerType"]').forEach(el=>el.addEventListener("change",()=>{appState.rule.triggerType=el.value;const e=eventOptions()[0];if(el.value==="event"&&e)appState.rule.eventId=e.id;rerender(onOpenEvents)}));
  host.querySelectorAll('input[name="lifecycle"]').forEach(el=>el.addEventListener("change",()=>{appState.rule.lifecycle=el.value;rerender(onOpenEvents)}));
  host.querySelectorAll('input[name="frequency"]').forEach(el=>el.addEventListener("change",()=>{appState.rule.strategy=el.value;rerender(onOpenEvents)}));
  host.querySelectorAll('input[name="linkMode"]').forEach(el=>el.addEventListener("change",()=>{appState.message.cozyLinkMode=el.value;if(el.value==="preset")appState.message.cozyLink=activeProduct().presetLinks.find(x=>x.id===appState.message.presetLinkId)?.uri||"";rerender(onOpenEvents)}));
  host.querySelectorAll("[data-preset-link]").forEach(el=>el.addEventListener("change",()=>{appState.message.presetLinkId=el.value;appState.message.cozyLink=activeProduct().presetLinks.find(x=>x.id===el.value)?.uri||""}));
  host.querySelectorAll("[data-custom-link]").forEach(el=>el.addEventListener("input",e=>{appState.message.cozyLink=e.target.value}));
  host.querySelectorAll("[data-message-key]").forEach(el=>{el.addEventListener("focus",()=>{appState.message.activeField=el.dataset.messageKey});el.addEventListener("input",()=>{selectedMessage()[el.dataset.messageKey]=el.value})});
  host.querySelectorAll("[data-placeholder]").forEach(el=>el.addEventListener("click",()=>{const target=host.querySelector(`[data-message-key="${el.dataset.target}"]`);if(!target)return;target.focus();const start=target.selectionStart??target.value.length;target.value=`${target.value.slice(0,start)}${el.dataset.placeholder}${target.value.slice(target.selectionEnd??start)}`;selectedMessage()[el.dataset.target]=target.value;target.selectionStart=target.selectionEnd=start+el.dataset.placeholder.length}));
  host.querySelectorAll("[data-open-language]").forEach(el=>el.addEventListener("click",()=>openLanguageDrawer({onClose:()=>rerender(onOpenEvents)})));
  host.querySelector("[data-open-events]")?.addEventListener("click",()=>{closeRuleDrawer();onOpenEvents?.()});
  host.querySelector("[data-next]")?.addEventListener("click",()=>{if(appState.ruleStep===1&&!selectedMessage().title.trim()){showToast("请先填写 English title","error");return}appState.ruleStep++;rerender(onOpenEvents)});
  host.querySelector("[data-prev]")?.addEventListener("click",()=>{appState.ruleStep--;rerender(onOpenEvents)});
  host.querySelector("[data-draft]")?.addEventListener("click",e=>saveButton(e.currentTarget,"规则草稿已保存"));
  host.querySelector("[data-enable]")?.addEventListener("click",e=>{const errors=validationListText();if(errors.length){showToast(`发布校验未通过：${errors[0]}`,"error");return}openConflict(true,e.currentTarget)});
  host.querySelectorAll("[data-fuse]").forEach(el=>el.addEventListener("click",()=>{const s=el.dataset.fuse;appState.fuseState.status=s;appState.fuseState.uniquePerMinute=s==="open"?121:s==="half-open"?102:38;appState.fuseState.quietMinutes=s==="half-open"?5:0;rerender(onOpenEvents);showToast(s==="open"?"已进入熔断并写入审计告警":s==="half-open"?"已进入半开状态，等待首个正常触发":"熔断已恢复")}));
}
function validationListText(){const out=[];const msg=selectedMessage();if(!appState.rule.name)out.push("规则名称");if(!msg.title.trim()||!msg.body.trim())out.push("English title/body");if(unsupportedTokens().length)out.push("未知占位符");if(invalidTokens().length)out.push("当前触发无法提供占位符");if(appState.message.cozyLinkMode==="custom"&&!linkValid(appState.message.cozyLink))out.push("cozy:// 深链格式");if(appState.rule.lifecycle==="continuous"&&!appState.rule.endEventId&&!appState.rule.limited)out.push("结束条件或受限模式");if(appState.rule.maxHours>168||appState.rule.maxCount>500)out.push("受限模式硬顶");return out}
function saveButton(btn,message){btn.disabled=true;btn.textContent="保存中…";setTimeout(()=>{showToast(message);btn.disabled=false;btn.textContent="保存草稿"},650)}
function openConflict(saveAfter=false){const modal=document.createElement("div");modal.className="modal-host";modal.innerHTML=`<div class="modal"><header class="modal-header"><h3>发布前冲突提示</h3><button class="icon-btn" data-modal-close>×</button></header><div class="modal-body"><div class="help-alert warning">发现同产品相同触发对象的 1 条低风险重叠规则。冲突只告警，不自动修改；频控仍按规则级策略执行。</div><div class="conflict-row"><strong>夜间溢奶安全提醒</strong><div class="secondary-cell">同产品 · 同关联键 ${esc(appState.rule.correlationKey)} · P1</div></div></div><footer class="modal-footer"><button class="el-btn" data-modal-close>返回修改</button>${saveAfter?'<button class="el-btn el-btn--primary" data-confirm-save>仍然启用</button>':""}</footer></div>`;document.body.appendChild(modal);modal.querySelectorAll("[data-modal-close]").forEach(x=>x.onclick=()=>modal.remove());modal.querySelector("[data-confirm-save]")?.addEventListener("click",e=>{e.currentTarget.disabled=true;e.currentTarget.textContent="保存中…";setTimeout(()=>{modal.remove();closeRuleDrawer();showToast("规则已保存并启用")},700)})}
export function closeRuleDrawer(){const host=$("#ruleDrawer");if(!host)return;host.classList.remove("is-open");setTimeout(()=>host.remove(),220);renderAnnotations(appState.tab,appState.tab==="rules"?"推送规则列表":"事件管理")}
